class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        vx = {'E': 1, 'W': -1, 'N': 0, 'S': 0}
        vy = {'N': 1, 'S': -1, 'E': 0, 'W': 0}
        best = 0
        for sx in (1, -1):
            for sy in (1, -1):
                cur = 0   # current prefix sum along this diagonal
                neg = 0   # count of opposing moves so far
                m = 0
                for c in s:
                    v = sx * vx[c] + sy * vy[c]
                    cur += v
                    if v < 0:
                        neg += 1
                    f = k if k < neg else neg  # min(k, neg)
                    t = cur + 2 * f
                    if t > m:
                        m = t
                if m > best:
                    best = m
        return best
```

This runs in O(n) time (4 passes over the string) and O(1) extra space, easily handling n = 10^5.

